INSERT INTO `agendas` VALUES
(2,'MEMPERINGATI HARI KEBANGKITAN NASIONAL TAHUN 2022','<div>Memperingati Hari Kebangkitan Nasional 2022,di Inspektorat ProvSU.<br><br>Hari kebangkitan Nasional dikarenakan tanggal lahirnya organisasi Budi Utomo tahun 1908. Momentum tersebut menjadi tonggak kebangkitan Nasional. Oleh karenanya pada tahun 2022 diperingati ke 114 tahun dengan tema Ayo bangkit. Tema tersebut merupakan semangat bagi kita utk terus bangkit dari pandemi selama 2 tahun melanda Indonesia.<br><br>Kini saatnya kita bangkit...<br><br>Untuk Sumut Bermartabat, Indonesia jaya<br><br>Memperingati Hari Kebangkitan Nasional 2022,di Inspektorat ProvSU.</div><div><br><br>Hari kebangkitan Nasional dikarenakan tanggal lahirnya organisasi Budi Utomo tahun 1908. Momentum tersebut menjadi tonggak kebangkitan Nasional. Oleh karenanya pada tahun 2022 diperingati ke 114 tahun dengan tema Ayo bangkit. Tema tersebut merupakan semangat bagi kita utk terus bangkit dari pandemi selama 2 tahun melanda Indonesia.<br><br>Kini saatnya kita bangkit...<br><br>Untuk Sumut Bermartabat, Indonesia jaya</div>','memperingati-hari-kebangkitan-nasional-tahun-2022',2472,'20230816125734.jpg','2022-08-09 17:00:00','2024-04-09 10:58:02'),
(3,'APEL PAGI SENIN 29 MEI 2023','<div>Senin (29/05) Inspektorat Provinsi Sumatera Utara melaksanakan Apel Pagi yang dilaksanakan&nbsp; rutin setiap hari senin sebelum melakukan aktivitas. Kegiatan apel pagi ini dipimpin langsung oleh Bapak Lasro Marbun selaku Inspektur Provinsi Sumatera Utara dan dihadiri oleh segenap manajemen serta para Auditor dan PPUPD serta pelaksana. Apel&nbsp; dimulai pukul 08.00 WIB sampai selesai bertempat di halaman Inspektorat Provinsi Sumatera Utara. Dalam kesempatan apel ini, Inspektur selaku pembina Apel menyampaikan amanat Gubernur Sumatera mengenai pentingnya pembangunan berkelanjutan khususnya pada Provinsi Sumatera Utara, kemudian Inspektur menambahkan bahwa sebagai insan APIP di Sumatera Utara, segenap jajaran Inspektorat Provinsi Sumatera Utara diminta untuk selalu bertindak profesional dalam bertugas dan dapat menjadi contoh teladan bagi PNS lainnya di Provinsi Sumatera Utara. (red)</div>','apel-pagi-senin-29-mei-2023',2453,'20230816130226.jpg','2023-05-28 17:00:00','2024-04-09 10:56:53'),
(4,'UPACARA HARLAH PANCASILA 2023 ITPROVSU','<div>Medan (01/06), Pelaksanaan Upacara Bendera dalam rangka memperingati Hari Lahir Pancasila Tahun 2023 Inspektorat Provinsi Sumatera Utara pada Hari Kamis (01/06/2023) dilaksanakan di Lapangan Upacara Inspektorat Provsu di Jlan KH. Wahid Hasyim No. 8 Medan.<br>Bertindak selaku Pembina Upacara Inspektur Pembantu III Bapak Ridwan, SH, mewakili Inspektur yang sedang bertugas di Jakarta. Hadir pada Pelaksanaan Upacara para Irban, para Kasubbag, para Auditor/PPUPD, para Pejabat pelaksana dan Non PNS yang ada pada Inspektorat Provinsi Sumatera Utara.<br>Ridwan SH dalam membacakan arahan Gubernur Sumatera Utara mengatakan bahwa dengan adanya peringatan hari lahir Pancasila1 Juni 1945, diharapkan kita mampu memberikan semangat pembaharuan bagi setiap pribadi bangsa yang harus diimplementasikan dengan tindakan prilaku kita sehari hari, nilai-nilai luhur pancasila perlu dibumikan kembali melalui berbagai kegiatan dilingkungan masyarakat ditengah-tengah keberagaman, karena pada saat ini pengamalan dan penghayatan nilai-nilai luhur pancasila sangat penting sebagai upaya untuk merekatkan kebersamaan, persatuan dan kesatuan bangsa yang majemuk ini&nbsp;<br>Upacara dilanjutkan dengan menyanyikan lagu nasional Garuda Pancasila dan Maju Tak Gentar kemudian diakhiri dengan doa. (FA)</div>','upacara-harlah-pancasila-2023-itprovsu',2496,'20230816130336.jpg','2023-05-31 17:00:00','2024-04-11 06:48:22'),
(5,'Entry Dan Exit Meeting BPK RI','<div>Pj.Gubernur Sumatera Utara membuka Entry Dan Exit Meeting BPK RI di Aula Raja Inal Siregar besama Jajaran Perangkat Daerah Provinsi SUmatera Utara,</div>','entry-dan-exit-meeting-bpk-ri',2426,'20231016073008.jpeg','2023-10-12 17:00:00','2024-04-11 00:26:26');
