(53,'LAPORAN ASET','laporan-aset-2','<p>Daftar Aset TA.2022</p><figure class=\"table\"><table><thead><tr><th><strong>No.</strong></th><th><strong>Nama Aset</strong></th><th colspan=\"2\"><strong>Nilai Perolehan</strong></th></tr></thead><tbody><tr><td>1.</td><td>Tanah</td><td>Rp.</td><td>17.865.100.000,00</td></tr><tr><td>2.</td><td>Alat Angkutan</td><td>Rp.</td><td>3.156.313.467,00</td></tr><tr><td>3.</td><td>Alat Kantor dan rumah tangga</td><td>Rp.&nbsp;</td><td>2.092.016.125,00</td></tr><tr><td>4.</td><td>Alat Studio Komunikasi dan Pemancar</td><td>Rp.&nbsp;</td><td>502.213.000,00</td></tr><tr><td>4.</td><td>Alat Laboratorium</td><td>Rp.&nbsp;</td><td>&nbsp; &nbsp; &nbsp; 38.770.000,00</td></tr><tr><td>5.</td><td>Komputer</td><td>Rp.</td><td>&nbsp; 1.181.641.020,00</td></tr><tr><td>6.</td><td>Alat Persenjataan</td><td>Rp.</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 76.715.000,00</td></tr><tr><td>6.</td><td>Gedung dan Bangunan</td><td>Rp.&nbsp;</td><td>33.995.448.981,95</td></tr><tr><td>7.</td><td>Jalan, Irigasi dan Jaringan</td><td>Rp.</td><td>&nbsp; &nbsp; &nbsp;928.753.961,89</td></tr><tr><td>8.</td><td>Aset tak berwujud</td><td>Rp.&nbsp;</td><td>&nbsp; &nbsp; &nbsp;834.180.000,00</td></tr></tbody></table></figure><p>&nbsp;</p><p><strong>&nbsp;</strong></p><p><i>Sumber :&nbsp;</i></p><p><i>Profil dan Budaya Kerja Inspektorat Provinsi Sumatera Utara Tahun 2023</i></p>','laporan','2024-04-04 15:16:46','2024-04-04 15:16:46'),
