INSERT INTO `popups` VALUES
(4,'Selamat Menunaikan Ibadah Puasa','20240404173849.gif','2024-04-01 17:00:00','2024-04-04 10:38:49');
INSERT INTO `tampilanppids` VALUES
(1,'profile','<div>Informasi merupakan kebutuhan pokok setiap orang bagi pengembangan pribadi dan lingkungan sosialnya serta merupakan bagian penting bagi ketahanan nasional. Hak memperoleh informasi merupakan hak asasi manusia dan keterbukaan informasi publik merupakan salah satu ciri penting negara demokratis yang menjunjung tinggi kedaulatan rakyat untuk mewujudkan penyelenggaraan negara yang baik.</div><div>&nbsp;</div><div>Pemberlakuan Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik (UU KIP) pada tanggal 30 April 2010 merupakan momentum penting dalam mendorong keterbukaan di Indonesia. Dalam mendukung semangat keterbukaan informasi, Provinsi Sumatera Utara telah ditetapkan Peraturan Gubernur Sumatera Utara Nomor 71 Tahun 2017 tentang Pedoman Pengelolaan Pelayanan Informasi dan Dokumentasi Pemerintah Provinsi Sumatera Utara yang ditindaklanjuti dengan penetapan Keputusan Gubernur Sumatera Utara Nomor 188.44/764/KPTS/2017 tentang Pejabat Pengelola Informasi dan Dokumentasi Provinsi Sumatera Utara.</div><div>&nbsp;</div><div>UU KIP telah memberikan landasan hukum terhadap hak setiap orang dalam memperoleh informasi publik. UU KIP mengamanatkan setiap badan publik mempunyai kewajiban dalam menyediakan dan melayani permohonan informasi publik secara cepat, tepat waktu, biaya ringan dan dengan cara sederhana. Untuk memberikan pelayanan informasi, setiap badan publik menunjuk Pejabat Pengelola Informasi dan Dokumentasi (PPID). Salah satu tugas PPID adalah menyediakan akses informasi publik bagi pemohon informasi. Terkait dengan tugas tersebut, PPID Provinsi Sumatera Utara menetapkan Standar Operasional Prosedur (SOP) Pejabat Pengelola Informasi dan Dokumentasi Provinsi Sumatera Utara melalui Keputusan Gubernur Sumatera Utara Nomor 188.44/765/KPTS/2017 tentang Standar Operasional Prosedur Pejabat Pengelola Informasi dan Dokumentasi Provinsi Sumatera Utara. Dengan adanya SOP ini, diharapkan implementasi UU KIP dapat berjalan efektif, sehingga hak dan kewajiban badan publik maupun pemohon informasi dapat dilaksanakan dengan optimal sesuai dengan tujuan UU KIP.</div>',NULL,NULL,'2024-02-11 01:53:58'),
(2,'visi','<div>Terwujudnya pelayanan informasi yanng transparan dan akuntabel untuk memenuhi hak pemohon informasi sesuai dengan ketentuan peraturan perundang- undangan yang berlaku.</div>',NULL,NULL,'2024-02-11 01:54:10'),
(3,'misi','<div>1.&nbsp; &nbsp; Meningkatkan pengelolaan dan pelayanan informasi yang berkualitas, benar dan bertanggung jawab.</div><div>2.&nbsp; &nbsp; Membangun dan mengembangkan sistem penyediaan dan layanan informasi.</div><div>3.&nbsp; &nbsp; Meningkatkan dan mengembangkan kompetensi dan kualitas SDM dalam bidang pelayanan informasi.</div><div>4.&nbsp; &nbsp; Mewujudkan keterbukaan informasi Pemerintah Provinsi Sumatera Utara dengan proses yang cepat, tepat, mudah dan sederhana.</div>',NULL,NULL,'2024-02-11 01:54:24'),
(4,'tugas dan fungsi','<div>PPID Utama bertugas:</div><div>&nbsp;</div><div>a.&nbsp; &nbsp; menyusun dan melaksanakan kebijakan informasi dan dokumentasi;</div><div>b.&nbsp; &nbsp; menyusun laporan pelaksanaan kebijakan informasi dan dokumentasi;</div><div>c.&nbsp; &nbsp; mengkoordinasikan dan mengkonsolidasikan pengumpulan bahan informasi dan dokumentasi dari PPID Pembantu;</div><div>d.&nbsp; &nbsp; menyimpan, mendokumentasikan, menyediakan dan memberi pelayanan informasi dan dokumentasi kepada publik;</div><div>e.&nbsp; &nbsp; melakukan verifikasi bahan informasi dan dokumentasi publik;</div><div>f.&nbsp; &nbsp; &nbsp;melakukan uji konsekuensi atas informasi dan dokumentasi yang dikecualikan;</div><div>g.&nbsp; &nbsp; melakukan pemutakhiran informasi dan dokumentasi;</div><div>h.&nbsp; &nbsp; menyediakan informasi dan dokumentasi untuk diakses oleh masyarakat;</div><div>i.&nbsp; &nbsp; &nbsp;melakukan pembinaan, pengawasan, evaluasi dan monitoring atas pelaksanaan kebijakan informasi dan dokumentasi yang dilakukan oleh PPID Pembantu;</div><div>j.&nbsp; &nbsp; &nbsp;melaksanakan rapat koordinasi dan rapat kerja secara berkala dan/atau sesuai kebutuhan dengan kebutuhan;</div><div>k.&nbsp; &nbsp; mengesahkan informasi dan dokumentasi yang layak untuk dipublikasikan;</div><div>l.&nbsp; &nbsp; &nbsp;menugaskan PPID Pembantu dan/atau pejabat fungsional untuk mengumpulkan, mengelola dan memelihara informasi dan dokumentasi; dan</div><div>m.&nbsp; membentuk tim fasilitasi penanganan sengketa informasi yang ditetapkan dengan keputusan Gubernur.</div><div>&nbsp;</div><div>&nbsp;</div><div>PPID Utama berwenang:</div><div>&nbsp;</div><div>a.&nbsp; &nbsp; menolak memberikan informasi dan dokumentasi yang dikecualikan sesuai dengan ketentuan peraturan perundang-undangan;</div><div>b.&nbsp; &nbsp; meminta dan memperoleh informasi dan dokumentasi dari PPID Pembantu;</div><div>c.&nbsp; &nbsp; mengkoordinasikan pemberian pelayanan informasi dan dokumentasi dengan PPID Pembantu;</div><div>d.&nbsp; &nbsp; menentukan atau menetapkan suatu informasi dan dokumentasi yang dapat diakses oleh publik; dan</div><div>e.&nbsp; &nbsp; menugaskan PPID Pembantu dan/atau Pejabat Fungsional untuk membuat, mengumpulkan serta memelihara informasi dan dokumentasi.</div><div>&nbsp;</div><div>&nbsp;</div><div>PPID Pembantu bertugas :</div><div>&nbsp;</div><div>a.&nbsp; &nbsp; membantu PPID Utama melaksanakan tanggung jawab, tugas dan kewenangannya;</div><div>b.&nbsp; &nbsp; menyampaikan informasi dan dokumentasi kepada PPID Utama dilakukan paling sedikit 6 (enam) bulan sekali atau sesuai kebutuhan;</div><div>c.&nbsp; &nbsp; melaksanakan kebijakan teknis informasi dan dokumentasi sesuai dengan tugas pokok dan fungsinya;</div><div>d.&nbsp; &nbsp; menjamin ketersediaan dan akselerasi layanan informasi dan dokumentasi bagi pemohon informasi publik secara cepat, tepat, berkualitas dengan mengedepankan prinsip-prinsip pelayanan prima;</div><div>e.&nbsp; &nbsp; mengumpulkan, mengolah dan mengompilasi bahan dan data lingkup SKPD untuk menjadi bahan informasi dan dokumentasi publik;</div><div>f.&nbsp; &nbsp; &nbsp;menyampaikan laporan pelaksanaan kebijakan teknis dan pelayanan informasi dan dokumentasi kepada PPID Utama secara berkala sesuai kebutuhan.</div><div>&nbsp;</div><div>&nbsp;</div><div>PPID Pembantu Sekretariat DPRD bertugas :</div><div>&nbsp;</div><div>a.&nbsp; &nbsp; menyampaikan, meminta, mengelola, menyimpan informasi dan dokumentasi kepada DPRD sesuai peraturan perundang-undangan;</div><div>b.&nbsp; &nbsp; mengkoordinasikan informasi dan dokumentasi kepada DPRD untuk menetapkan informasi dan dokumentasi yang dapat diakses oleh publik.</div>',NULL,NULL,'2024-02-11 01:54:49');
